       ```java
       private void adjustAfterWidthChange(int oldWidth, int newWidth, int columnToSet, int newNextColumnIndex) {
           if (oldWidth == 2 && newWidth == 1) {
               shiftTail(mText, newNextColumnIndex, 1);
               mText[newNextColumnIndex] = ' ';
               ++mSpaceUsed;
