/** An Operating System Controls (OSC) Set Text Parameters. May come here from BEL or ST. */
private void doOscSetTextParameters(String bellOrStringTerminator) {
    int value = -1;
    String textParameter = "";
    // Extract initial $value from initial "$value;..." string.
    for (int mOSCArgTokenizerIndex = 0; mOSCArgTokenizerIndex < mOSCOrDeviceControlArgs.length(); mOSCArgTokenizerIndex++) {
        char b = mOSCOrDeviceControlArgs.charAt(mOSCArgTokenizerIndex);
        if (b == ';') {
            textParameter = mOSCOrDeviceControlArgs.substring(mOSCArgTokenizerIndex + 1);
            break;
        } else if (b >= '0' && b <= '9') {
            value = ((value < 0) ? 0 : value * 10) + (b - '0');
        } else {
            unknownSequence(b);
            return;
        }
    }

    switch (value) {
        case 0: // Change icon name and window title to T.
        case 1: // Change icon name to T.
        case 2: // Change window title to T.
            setTitle(textParameter);
            break;
        case 4:
            if (!oscChangeColors(textParameter)) return;
            break;
        case 10: // Set foreground color.
        case 11: // Set background color.
        case 12: // Set cursor color.
            oscSetOrReportSpecialColors(value, textParameter, bellOrStringTerminator);
            break;
        case 52: // Manipulate Selection Data. Skip the optional first selection parameter(s).
            oscManipulateSelection(textParameter);
            break;
        case 104:
            oscResetColors(textParameter);
            break;
        case 110: // Reset foreground color.
        case 111: // Reset background color.
        case 112: // Reset cursor color.
            mColors.reset(TextStyle.COLOR_INDEX_FOREGROUND + (value - 110));
            mSession.onColorsChanged();
            break;
        case 119: // Reset highlight color.
            break;
        default:
            unknownParameter(value);
            break;
    }
    finishSequence();
}

/** OSC 52 — copy base64-decoded text to clipboard. Skips the optional selection-type prefix before ';'. */
private void oscManipulateSelection(String textParameter) {
    int startIndex = textParameter.indexOf(";") + 1;
    try {
        String clipboardText = new String(Base64.decode(textParameter.substring(startIndex), 0), StandardCharsets.UTF_8);
        mSession.onCopyTextToClipboard(clipboardText);
    } catch (Exception e) {
        Logger.logError(mClient, LOG_TAG, "OSC Manipulate selection, invalid string '" + textParameter + "");
    }
}

