private void doCsiSelectiveErase(int b) {
    mAboutToAutoWrap = false;
    int fillChar = ' ';
    int startCol = -1;
    int startRow = -1;
    int endCol = -1;
    int endRow = -1;
    boolean justRow = (b == 'K');
    switch (getArg0(0)) {
        case 0: // Erase from the active position to the end, inclusive (default).
            startCol = mCursorCol;
