725	    private void doCsiDollar(int b) {
726	        boolean originMode = isDecsetInternalBitSet(DECSET_BIT_ORIGIN_MODE);
727	        int effectiveTopMargin = originMode ? mTopMargin : 0;
728	        int effectiveBottomMargin = originMode ? mBottomMargin : mRows;
729	        int effectiveLeftMargin = originMode ? mLeftMargin : 0;
730	        int effectiveRightMargin = originMode ? mRightMargin : mColumns;
731	        switch (b) {
732	            case 'v': // DECCRA — Copy rectangular area (http://vt100.net/docs/vt510-rm/DECCRA).
733	                doCsiRectCopy(effectiveTopMargin, effectiveLeftMargin);
734	                break;
735	            case '{': // DECSERA — Selective erase rectangular area.
736	            case 'x': // DECFRA — Fill rectangular area.
737	            case 'z': // DECERA — Erase rectangular area.
738	                doCsiRectFillOrErase(b, effectiveTopMargin, effectiveBottomMargin, effectiveLeftMargin, effectiveRightMargin);
739	                break;
740	            case 'r': // "${CSI}${TOP}${LEFT}${BOTTOM}${RIGHT}${ATTRIBUTES}$r"
741	                // Change attributes in rectangular area (DECCARA - http://vt100.net/docs/vt510-rm/DECCARA).
742	            case 't': // "${CSI}${TOP}${LEFT}${BOTTOM}${RIGHT}${ATTRIBUTES}$t"
743	                // Reverse attributes in rectangular area (DECRARA - http://www.vt100.net/docs/vt510-rm/DECRARA).
744	                doCsiRectAttrChange(b, effectiveTopMargin, effectiveBottomMargin, effectiveLeftMargin, effectiveRightMargin);
745	                break;
746	            default:
747	                unknownSequence(b);
748	        }
749	    }
750	
751	    /**
752	     * DECCRA ($v): copy rectangular area.
753	     * "If Pbs is greater than Pts, or Pls is greater than Prs, the terminal ignores DECCRA.
754	     * The coordinates of the rectangular area are affected by the setting of origin mode (DECOM).
755	     * DECCRA is not affected by the page margins.
756	     * The copied text takes on the line attributes of the destination area.
757	     * If the value of Pt, Pl, Pb, or Pr exceeds the width or height of the active page, then the value
758	     * is treated as the width or height of that page.
759	     * If the destination area is partially off the page, then DECCRA clips the off-page data.
760	     * DECCRA does not change the active cursor position."
761	     */
762	    private void doCsiRectCopy(int effectiveTopMargin, int effectiveLeftMargin) {
763	        int topSource = Math.min(getArg(0, 1, true) - 1 + effectiveTopMargin, mRows);
764	        int leftSource = Math.min(getArg(1, 1, true) - 1 + effectiveLeftMargin, mColumns);
765	        // Inclusive, so do not subtract one:
766	        int bottomSource = Math.min(Math.max(getArg(2, mRows, true) + effectiveTopMargin, topSource), mRows);
767	        int rightSource = Math.min(Math.max(getArg(3, mColumns, true) + effectiveLeftMargin, leftSource), mColumns);
768	        // int sourcePage = getArg(4, 1, true);
769	        int destionationTop = Math.min(getArg(5, 1, true) - 1 + effectiveTopMargin, mRows);
770	        int destinationLeft = Math.min(getArg(6, 1, true) - 1 + effectiveLeftMargin, mColumns);
771	        // int destinationPage = getArg(7, 1, true);
772	        int heightToCopy = Math.min(mRows - destionationTop, bottomSource - topSource);
773	        int widthToCopy = Math.min(mColumns - destinationLeft, rightSource - leftSource);
774	        mScreen.blockCopy(leftSource, topSource, widthToCopy, heightToCopy, destinationLeft, destionationTop);
775	    }
