777	    /** DECSERA (${{), DECFRA ($x), DECERA ($z): selectively erase, fill, or erase a rectangular area. */
778	    private void doCsiRectFillOrErase(int b, int effectiveTopMargin, int effectiveBottomMargin,
779	                                       int effectiveLeftMargin, int effectiveRightMargin) {
780	        boolean erase = b != 'x';
781	        boolean selective = b == '{';
782	        // Only DECSERA keeps visual attributes, DECERA does not:
783	        boolean keepVisualAttributes = erase && selective;
784	        int argIndex = 0;
785	        int fillChar = erase ? ' ' : getArg(argIndex++, -1, true);
786	        // "Pch can be any value from 32 to 126 or from 160 to 255. If Pch is not in this range, then the
787	        // terminal ignores the DECFRA command":
788	        if ((fillChar >= 32 && fillChar <= 126) || (fillChar >= 160 && fillChar <= 255)) {
789	            // "If the value of Pt, Pl, Pb, or Pr exceeds the width or height of the active page, the value
790	            // is treated as the width or height of that page."
791	            int top = Math.min(getArg(argIndex++, 1, true) + effectiveTopMargin, effectiveBottomMargin + 1);
792	            int left = Math.min(getArg(argIndex++, 1, true) + effectiveLeftMargin, effectiveRightMargin + 1);
793	            int bottom = Math.min(getArg(argIndex++, mRows, true) + effectiveTopMargin, effectiveBottomMargin);
794	            int right = Math.min(getArg(argIndex, mColumns, true) + effectiveLeftMargin, effectiveRightMargin);
795	            long style = getStyle();
796	            for (int row = top - 1; row < bottom; row++)
797	                for (int col = left - 1; col < right; col++)
798	                    if (!selective || (TextStyle.decodeEffect(mScreen.getStyleAt(row, col)) & TextStyle.CHARACTER_ATTRIBUTE_PROTECTED) == 0)
799	                        mScreen.setChar(col, row, fillChar, keepVisualAttributes ? mScreen.getStyleAt(row, col) : style);
800	        }
801	    }
