803	    /** DECCARA ($r) / DECRARA ($t): change or reverse visual attributes in a rectangular area. */
804	    private void doCsiRectAttrChange(int b, int effectiveTopMargin, int effectiveBottomMargin,
805	                                      int effectiveLeftMargin, int effectiveRightMargin) {
806	        boolean reverse = b == 't';
807	        // FIXME: "coordinates of the rectangular area are affected by the setting of origin mode (DECOM)".
808	        int top = Math.min(getArg(0, 1, true) - 1, effectiveBottomMargin) + effectiveTopMargin;
809	        int left = Math.min(getArg(1, 1, true) - 1, effectiveRightMargin) + effectiveLeftMargin;
810	        int bottom = Math.min(getArg(2, mRows, true) + 1, effectiveBottomMargin - 1) + effectiveTopMargin;
811	        int right = Math.min(getArg(3, mColumns, true) + 1, effectiveRightMargin - 1) + effectiveLeftMargin;
812	        if (mArgIndex >= 4) {
813	            clampArgIndex();
814	            for (int i = 4; i <= mArgIndex; i++) {
815	                int bits = 0;
816	                boolean setOrClear = true; // True if setting, false if clearing.
817	                switch (getArg(i, 0, false)) {
818	                    case 0: // Attributes off (no bold, no underline, no blink, positive image).
819	                        bits = (TextStyle.CHARACTER_ATTRIBUTE_BOLD | TextStyle.CHARACTER_ATTRIBUTE_UNDERLINE | TextStyle.CHARACTER_ATTRIBUTE_BLINK
820	                            | TextStyle.CHARACTER_ATTRIBUTE_INVERSE);
821	                        if (!reverse) setOrClear = false;
822	                        break;
